package com.axiom.analysis; import com.axiom.analysis.classification.ExplainableFailureClassifier; import com.axiom.domain.failure.FailureClassification; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.assertThat;
class ExplainableFailureClassifierTest {private final ExplainableFailureClassifier c=new ExplainableFailureClassifier();@Test void oomBeatsGenericBuildFailure(){var r=c.classify("java.lang.OutOfMemoryError: Java heap space; command failed with exit code 1",null);assertThat(r.classification()).isEqualTo(FailureClassification.RESOURCE_EXHAUSTION);}@Test void assertionIsNotProductRegression(){assertThat(c.classify("AssertionError: expected true",null).classification()).isEqualTo(FailureClassification.TEST_FAILURE);}@Test void weakNoEvidenceIsUnknown(){assertThat(c.classify("ordinary status line",null).classification()).isEqualTo(FailureClassification.UNKNOWN);}}
